INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('buch-wien-2026-messe-wien-programm-tickets-oeffnungszeiten','Buch Wien 2026: Programm, Tickets und Öffnungszeiten','Die Buch Wien 2026 läuft von 25. bis 29. November in der Messe Wien: mehr als 500 Programmpunkte auf acht Bühnen, ein neuer Ukraine-Schwerpunkt und Tickets ab 12 Euro.','Die **Buch Wien 2026** öffnet am Mittwoch, 25. November, ihre Tore in der Messe Wien im zweiten Bezirk. Bis Sonntag, 29. November, bespielt Österreichs größte Buchmesse zwei Messehallen mit mehr als 500 Programmpunkten auf acht Bühnen. Veranstalter ist der Hauptverband des Österreichischen Buchhandels (HVB), die Gesamtleitung liegt bei Oliver Zille, dem früheren Direktor der Leipziger Buchmesse.

## Buch Wien 2026: Eröffnung und Highlights

Den Auftakt macht am Mittwochabend der Publizist und Moderator Michel Friedman mit seiner Festrede auf der ORF-Bühne. Im Anschluss stellt Literaturnobelpreisträger László Krasznahorkai sein Buch „Zsömle ist weg“ vor. Ebenfalls angekündigt sind Friedensnobelpreisträgerin Oleksandra Matviichuk sowie Elias Hirschl und Valeria Gordeev, die beide auf der Shortlist des Deutschen Buchpreises standen.

Laut Vorschauberichten treten im Lauf der Messetage auch Robert Habeck, Alt-Bundespräsident Heinz Fischer, VfGH-Präsident Christoph Grabenwarter und die Extremismusforscherin Julia Ebner auf. Für den Eröffnungsabend ist zudem eine Poetry-Slam-Nacht geplant.

## Neuer Schwerpunkt „Update Ukraine“

Erstmals gibt es mit „Update Ukraine“ einen eigenen Programmschwerpunkt zu ukrainischen Autorinnen, Autoren und Kunstschaffenden, die unter Kriegsbedingungen arbeiten. Kuratiert wird die Reihe von der in Wien lebenden Schriftstellerin Tanja Maljartschuk. Zu den Gästen zählt neben Matviichuk auch der Schriftsteller Serhij Zhadan.

## Neue Bühnen, Podcasts und Kinderprogramm

Die Messe hat ihr Hallenkonzept umgebaut:

- **Halle C:** Kinder- und Jugendbücher haben einen ruhigeren Platz bekommen, dazu eine Messebuchhandlung und ein Kaffeehaus. Rund 140 Veranstaltungen richten sich an junges Publikum.
- **Halle D:** Hier gibt es einen neuen Gemeinschaftsstand für Sach- und Fachbuch sowie eine neue Bühne mit 200 Sitzplätzen.
- **Wissenschaft:** Ein Bereich unter dem Motto „Science zum Anfassen“ widmet sich Technik, Mobilität und der Stadt der Zukunft.

Ausgebaut wurde auch das Angebot an Live-Podcasts, unter anderem mit Formaten von NDR, der ZEIT und dem STANDARD. Neu ist außerdem ein Pub-Quiz zum Genre New Adult.

Einen eigenen Schwerpunkt erhält Christine Nöstlinger, die heuer 90 Jahre alt geworden wäre. Gemeinsam mit der Buchstabenfabrik erinnert die Messe mit Figuren aus ihren Büchern und Fotos an die Wiener Kinderbuchautorin. Wer nach dem Messebesuch noch Programm sucht, findet in unserem Überblick über die [Ausstellungen in Wien im Herbst 2026](/artikel/ausstellungen-wien-herbst-2026-ueberblick) weitere Tipps.

## Öffnungszeiten und Tickets der Buch Wien

Die Messe findet in den Hallen C und D der Messe Wien (Trabrennstraße) statt. Die nächste U-Bahn-Station ist Krieau (U2). Die Öffnungszeiten:

1. Mittwoch, 25. November: 16.30 bis 21.30 Uhr
2. Donnerstag, 26. November: 9 bis 18 Uhr
3. Freitag, 27. November: 9 bis 18 Uhr
4. Samstag, 28. November: 10 bis 18 Uhr
5. Sonntag, 29. November: 10 bis 17 Uhr

Ein Tagesticket kostet im Vorverkauf 24 Euro, ermäßigt 19 Euro. Kinder bis 13 Jahre haben freien Eintritt. Am Donnerstag gibt es für Studierende bis 27 Jahre ein Uni-Tagesticket um 12 Euro. Das vollständige Programm mit allen Lesungen und Gesprächen veröffentlicht der Veranstalter online auf buchwien.at.

Wer die Messe mit einem vorweihnachtlichen Spaziergang verbinden will: Die [Weihnachtsmärkte in Wien](/artikel/weihnachtsmaerkte-wien-2026-15-maerkte-814-staende-termine) haben bereits geöffnet, der Prater liegt direkt neben dem Messegelände.','kultur','Ausstellungen','wien','news','Presseinfo Redaktion','/assets/img/artikel/buch-wien-2026-messe-wien-programm-tickets-oeffnungszeiten.webp','Hauptverband des Österreichischen Buchhandels','https://buecher.at/buch-wien-2026-programm-veroeffentlicht/','published','2026-11-25T11:55:00.000Z','2026-11-25T11:55:00.000Z','Buch Wien 2026: Programm, Tickets, Zeiten','Buch Wien 2026: Von 25. bis 29. November über 500 Programmpunkte auf acht Bühnen in der Messe Wien. Hier alle Öffnungszeiten, Tickets und Highlights.','Buch Wien 2026','["Buch Wien 2026","Buch Wien","Buchmesse Wien","Buch Wien Tickets","Buch Wien Öffnungszeiten","Buch Wien Programm 2026","Messe Wien November 2026","Update Ukraine Buch Wien","Christine Nöstlinger 90"]','Buch Wien 2026: Bücherstände und Besucher in einer Messehalle in Wien','Photorealistic wide shot of a bright modern book fair hall in Vienna, long wooden tables stacked with colourful books without readable titles, visitors seen from behind browsing, a small stage with empty chairs in the background, warm natural light, no text, no logos, no readable signs, no identifiable people','[{"q":"Wann findet die Buch Wien 2026 statt?","a":"Die Buch Wien 2026 läuft von Mittwoch, 25. November, bis Sonntag, 29. November 2026, in den Hallen C und D der Messe Wien."},{"q":"Was kostet ein Ticket für die Buch Wien?","a":"Das Tagesticket kostet im Vorverkauf 24 Euro, ermäßigt 19 Euro. Kinder bis 13 Jahre sind frei, Studierende bis 27 zahlen am Donnerstag 12 Euro."},{"q":"Wie komme ich zur Buch Wien?","a":"Am einfachsten mit der U2 bis zur Station Krieau, von dort sind es nur wenige Gehminuten zur Messe Wien."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, cate